diff:
diff --git a/src/attachments/send.ts b/src/attachments/send.ts
--- a/src/attachments/send.ts
+++ b/src/attachments/send.ts
@@ -1,2 +1,2 @@
 import {encodeAttachment} from "./encode";
-export const sendAttachment = (text: string): string => encodeAttachment(text);
+export const sendAttachment = (text: string, compact = false): string => encodeAttachment(text, compact);
diff --git a/src/attachments/encode.ts b/src/attachments/encode.ts
--- a/src/attachments/encode.ts
+++ b/src/attachments/encode.ts
@@ -1,2 +1,2 @@
 import {renderAttachment} from "./render";
-export const encodeAttachment = (text: string): string => renderAttachment(text);
+export const encodeAttachment = (text: string, compact: boolean): string => renderAttachment(text, compact);
diff --git a/src/attachments/render.ts b/src/attachments/render.ts
--- a/src/attachments/render.ts
+++ b/src/attachments/render.ts
@@ -1 +1 @@
-export const renderAttachment = (text: string): string => text;
+export const renderAttachment = (text: string, compact: boolean): string => compact ? text.replace(/\s+/g, " ") : text;
diff --git a/src/export.ts b/src/export.ts
--- a/src/export.ts
+++ b/src/export.ts
@@ -1,2 +1,2 @@
 import {sendAttachment} from "./attachments/send";
-export const exportAttachment = (text: string) => sendAttachment(text);
+export const exportAttachment = (text: string) => sendAttachment(text, true);
